___CSS_LOADER_EXPORT___.push([module.id, `:host {
    display: block;
    height: 100%;
}

.header-panel {
    background-color: var(--headerBackground);
    color: var(--headerColor);
    position: absolute;
    top: 0px;
    left: 0px;
    height: 36px;
    width: 100%;
    text-align: center;
    line-height: 36px;
    border-bottom: 1px solid var(--headerBorder);
}

.header-panel mat-icon {
    display: inline-block;
    vertical-align: text-top;
}

.work-panel {
    position: absolute;
    top: 37px;
    left: 0px;
    right: 0px;
    bottom: 0px;
    background-color: var(--mat-table-background-color);
    overflow: hidden;
}

.container {
    display: flex;
    flex-direction: column;
    min-width: 300px;
    position: absolute;
    bottom: 0px;
    top: 0px;
    left: 0px;
    right: 0px;
    overflow-y: auto;
}

.mat-table {
    width: 100%;
    border-bottom: 1px solid rgb(81, 81, 81);
}

.mat-row {
    min-height: 40px;
    height: 43px;
}

.mat-cell {
    font-size: 13px;
}

.loading-spinner {
    display: flex;
    justify-content: center;
    align-items: center;
    flex: 1;
    padding: 40px;
}

.empty-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    flex: 1;
    padding: 40px;
    opacity: 0.6;
}

.empty-state mat-icon {
    font-size: 48px;
    width: 48px;
    height: 48px;
    margin-bottom: 16px;
}

.fab-add {
    position: absolute;
    bottom: 24px;
    right: 24px;
    z-index: 100;
}

.mat-column-select {
    overflow: visible;
    flex: 0 0 80px;
}

.mat-column-name {
    flex: 1 1 120px;
}

.mat-column-description {
    flex: 3 1 180px;
}

.mat-column-entries {
    flex: 1 1 120px;
}

.mat-column-options {
    flex: 0 0 60px;
}

.mat-column-remove {
    flex: 0 0 60px;
}

.selectidthClass {
    flex: 0 0 50px;
}
