  display: block;
  height: 100%;
  min-height: 0;
  color: #edf6ff;
  background: #102d48;
  font: 14px "Microsoft YaHei", "Segoe UI", sans-serif;
  color-scheme: dark;
}

.workspace {
  height: 100%;
  display: grid;
  grid-template-columns: 200px minmax(0, 1fr);
  grid-template-rows: 50px minmax(0, 1fr);
  overflow: hidden;
}

.workspace-header {
  grid-column: 1/-1;
  display: flex;
  gap: 12px;
  align-items: center;
  padding: 6px 12px;
  background: #194567;
  border-bottom: 1px solid #487393;
  min-width: 0;
}

.workspace-header strong {
  font-size: 16px;
  white-space: nowrap;
}

.page-title {
  padding-left: 12px;
  border-left: 1px solid #658ba6;
}

.health {
  margin-left: auto;
  color: #c2d7e8;
  font-size: 12px;
}

.user {
  color: #edf6ff;
}

button, a {
  font: inherit;
  color: inherit;
}

button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  cursor: pointer;
  background: #205474;
  border: 1px solid #658ba6;
  border-radius: 6px;
  padding: 5px 10px;
  min-height: 34px;
}

button:hover, a:hover {
  background: #29688d;
}

button:focus-visible, a:focus-visible {
  outline: 3px solid #68d4ff;
  outline-offset: -3px;
}

.workspace-nav {
  grid-row: 2;
  overflow: auto;
  min-height: 0;
  background: #194567;
  padding: 8px;
  border-right: 1px solid #487393;
  scrollbar-color: #81a5be #194567;
}

.workspace-nav section {
  margin: 4px 0 10px;
}

.workspace-nav a, .nav-group, .collapse-toggle {
  display: flex;
  width: 100%;
  min-height: 40px;
  align-items: center;
  gap: 10px;
  border: 0;
  text-decoration: none;
  text-align: left;
  border-radius: 6px;
  background: transparent;
  padding: 8px;
  box-sizing: border-box;
}

.workspace-nav a {
  padding-left: 18px;
  color: #c2d7e8;
}

.workspace-nav a.current {
  color: #102d48;
  background: #9edfff;
  font-weight: 600;
}

.workspace-nav a:hover {
  background: #2c668a;
  color: #fff;
}

.nav-group {
  font-weight: 600;
}

.chevron {
  margin-left: auto;
}

.workspace-nav mat-icon {
  width: 22px;
  height: 22px;
  font-size: 22px;
  flex: none;
}

.workspace-content {
  grid-column: 2;
  grid-row: 2;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  position: relative;
  background: #102d48;
}

.menu-toggle, .backdrop {
  display: none;
}

.compact {
  grid-template-columns: 64px minmax(0, 1fr);
}

.compact .workspace-nav {
  padding: 8px 4px;
}

.compact .workspace-nav span, .compact .chevron {
  display: none;
}

.compact .workspace-nav a {
  padding-left: 12px;
}

.compact .nav-group {
  padding-left: 12px;
}

@media (max-width: 1400px) {
  .health {
    display: none;
  }
  .page-title {
    margin-right: auto;
  }
}
@media (max-width: 1024px) {
  .workspace, .compact {
    grid-template-columns: minmax(0, 1fr);
  }
  .workspace-content {
    grid-column: 1;
  }
  .menu-toggle {
    display: inline-flex;
  }
  .workspace-nav {
    display: none;
    position: absolute;
    top: 50px;
    bottom: 0;
    left: 0;
    width: 240px;
    z-index: 1001;
  }
  .drawer-open .workspace-nav {
    display: block;
  }
  .compact .workspace-nav span, .compact .chevron {
    display: initial;
  }
  .backdrop {
    display: block;
    position: absolute;
    inset: 50px 0 0;
    width: 100%;
    background: rgba(5, 20, 38, 0.6);
    border: 0;
    border-radius: 0;
    z-index: 1000;
  }
  .collapse-toggle {
    display: none;
  }
  .workspace-header {
    gap: 8px;
  }
  .workspace-header .page-title, .workspace-header .user {
    display: none;
  }
  .workspace-header strong {
    margin-right: auto;
  }
}
@media (max-width: 520px) {
  .workspace-header strong {
    font-size: 14px;
  }
  .workspace-header button {
    font-size: 12px;
    padding: 5px;
  }
  .workspace-header button:has(mat-icon) {
    padding: 4px;
  }
  .workspace-header {
    padding-inline: 6px;
  }
