    display: block;
}

.cam-tile {
    position: relative;
    background: #0b1420;
    border: 1px solid var(--sc-line, #1f3145);
    border-radius: var(--sc-r, 5px);
    overflow: hidden;
    transition: border-color 140ms ease;
}

.cam-tile--live { border-color: rgba(46, 204, 113, 0.5); }
.cam-tile--error { border-color: rgba(255, 84, 104, 0.5); }

.cam-tile__frame {
    position: relative;
    width: 100%;
    aspect-ratio: 16 / 9;
    background:
        repeating-linear-gradient(45deg, #0b1420 0 8px, #0d1826 8px 16px);
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

.cam-tile__frame img,
.cam-tile__frame video {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    object-fit: contain;
    background: #05090f;
}

.cam-tile__placeholder {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 8px;
    color: var(--sc-ink-3, #66798f);
    background: rgba(6, 12, 20, 0.72);
    z-index: 2;
}

.cam-err-icon {
    font-size: 34px !important;
    width: 34px !important;
    height: 34px !important;
    color: var(--sc-alarm, #ff5468);
}

.cam-err-code {
    font-family: var(--sc-mono, monospace);
    font-size: 11px;
    color: var(--sc-alarm, #ff5468);
    max-width: 90%;
    text-align: center;
    word-break: break-all;
}

.cam-retry { height: 26px; }

.cam-idle { font-size: 12px; }

/* ---- OSD overlay (on-screen display, SCADA style) ---- */

.cam-tile__osd {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 4px 8px;
    background: linear-gradient(180deg, transparent, rgba(4, 9, 15, 0.88));
    font-size: 11px;
    z-index: 3;
    pointer-events: none;
}

.cam-name {
    color: var(--sc-ink, #e8f0fa);
    font-weight: 600;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    flex: 1 1 auto;
}

.cam-badge {
    font-family: var(--sc-mono, monospace);
    font-size: 9.5px;
    letter-spacing: 0.05em;
    padding: 1px 5px;
    border-radius: 3px;
    background: rgba(61, 155, 255, 0.18);
    color: var(--sc-accent, #3d9bff);
    border: 1px solid rgba(61, 155, 255, 0.3);
}

.cam-badge--ai {
    background: rgba(255, 176, 32, 0.18);
    color: var(--sc-warn, #ffb020);
    border-color: rgba(255, 176, 32, 0.35);
}

@media (prefers-reduced-motion: reduce) {
    .cam-tile { transition: none; }
}

/* ---------------------------------------------------------------- OSD layer */
/* 视数融合: on-screen display overlaid on the video, 4 anchored corners. */

.cam-osd {
    position: absolute;
    inset: 0;
    z-index: 5;
    pointer-events: none;
    font-family: var(--sc-mono, monospace);
    font-size: 11.5px;
    line-height: 1.35;
    text-shadow: 0 1px 3px rgba(0, 0, 0, 0.95);
}

.cam-osd__corner {
    position: absolute;
    max-width: 62%;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.cam-osd__corner--tl { top: 6px; left: 7px; align-items: flex-start; text-align: left; }
.cam-osd__corner--tr { top: 6px; right: 7px; align-items: flex-end; text-align: right; }
.cam-osd__corner--bl { bottom: 26px; left: 7px; align-items: flex-start; text-align: left; }
.cam-osd__corner--br { bottom: 26px; right: 7px; align-items: flex-end; text-align: right; }

.cam-osd__line {
    padding: 1px 5px;
    border-radius: 2px;
    background: rgba(6, 12, 20, 0.62);
    border-left: 2px solid rgba(61, 155, 255, 0.75);
    color: #eaf3ff;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.cam-osd__corner--tr .cam-osd__line,
.cam-osd__corner--br .cam-osd__line {
    border-left: none;
    border-right: 2px solid rgba(61, 155, 255, 0.75);
}

/* live process value: emphasise the number */
.cam-osd__line--val {
    font-size: 13px;
    font-weight: 600;
    color: var(--sc-accent-2, #17b8a6);
    border-left-color: rgba(23, 184, 166, 0.85);
}

.cam-osd__corner--br .cam-osd__line--val {
    border-right-color: rgba(23, 184, 166, 0.85);
}

/* stale / bad-quality tag -> alarm colour, never rely on colour alone */
.cam-osd__line--bad {
    color: var(--sc-alarm, #ff5468);
    border-left-color: rgba(255, 84, 104, 0.9);
}

.cam-osd__corner--tr .cam-osd__line--bad,
.cam-osd__corner--br .cam-osd__line--bad {
    border-right-color: rgba(255, 84, 104, 0.9);
}

@media (prefers-reduced-motion: reduce) {
    .cam-osd__line { transition: none; }
}

/* ---------------------------------------------------------- detection layer */
/* AI 视频分析: normalised boxes drawn over the video. The caption sits above the
   box so it stays readable even when the target hugs the frame edge. */

.cam-det {
    position: absolute;
    inset: 0;
    z-index: 4;
    pointer-events: none;
    font-family: var(--sc-mono, monospace);
}

.cam-det__box {
    position: absolute;
    border: 1.5px solid var(--sc-warn, #ffb020);
    border-radius: 2px;
    box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.55) inset;
    background: rgba(255, 176, 32, 0.08);
}

.cam-det__tag {
    position: absolute;
    left: -1.5px;
    bottom: 100%;
    margin-bottom: 1px;
    padding: 0 4px;
    font-size: 10px;
    line-height: 14px;
    white-space: nowrap;
    color: #0b1420;
    background: var(--sc-warn, #ffb020);
    border-radius: 2px;
}
