  display: block;
  height: 100%;
  width: 100%;
  background: #111;
}

.ar-shell {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  color: #f7f9fb;
  font-family: "Segoe UI Symbol", "Roboto-Regular", "Helvetica Neue", sans-serif;
}

.ar-video {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  background: #111;
}

.ar-topbar {
  position: absolute;
  top: 12px;
  left: 12px;
  right: 12px;
  z-index: 3;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  pointer-events: none;
}

.ar-title {
  font-size: 18px;
  font-weight: 600;
  line-height: 22px;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.55);
}

.ar-status {
  margin-top: 3px;
  font-size: 12px;
  color: rgba(255, 255, 255, 0.78);
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.55);
}

.ar-manual {
  pointer-events: auto;
}

.ar-manual select {
  min-width: 180px;
  height: 34px;
  border: 1px solid rgba(255, 255, 255, 0.28);
  border-radius: 4px;
  background: rgba(20, 24, 28, 0.82);
  color: #fff;
  padding: 0 8px;
  font-size: 13px;
}

.ar-error,
.ar-empty,
.ar-message {
  position: absolute;
  left: 50%;
  top: 50%;
  z-index: 4;
  max-width: min(460px, 100% - 32px);
  transform: translate(-50%, -50%);
  padding: 14px 16px;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 6px;
  background: rgba(20, 24, 28, 0.88);
  color: #fff;
  font-size: 14px;
  text-align: center;
}

.ar-error {
  border-color: rgba(255, 120, 120, 0.65);
}

.ar-message {
  border-color: rgba(140, 190, 255, 0.65);
}

.ar-debug-lines {
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 12px;
  z-index: 9;
  overflow: hidden;
  padding: 6px 8px;
  border-radius: 4px;
  background: rgba(0, 0, 0, 0.68);
  color: #9df0b2;
  font-size: 11px;
  line-height: 1.35;
}

.ar-debug-lines div {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@media (max-width: 720px) {
  .ar-topbar {
    align-items: stretch;
    flex-direction: column;
  }
  .ar-manual select {
    width: 100%;
  }
  .ar-marker-card {
    left: 12px !important;
    right: 12px;
    width: auto;
    transform: none;
  }
}
.ar-marker-card {
  position: absolute;
  left: 50%;
  top: 50%;
  min-width: 220px;
  max-width: min(520px, 100vw - 32px);
  max-height: min(520px, 100vh - 32px);
  overflow: auto;
  transform: translate(-50%, -50%);
  background: rgba(0, 0, 0, 0.25);
  z-index: 8;
}

.ar-marker-title {
  font-size: 13px;
  opacity: 0.75;
  background: rgba(0, 0, 0, 0.25);
  color: #fff;
}

.ar-marker-view {
  min-width: 300px;
  min-height: 220px;
}

.ar-marker-view app-scadia-view {
  display: block;
  min-width: 300px;
  min-height: 220px;
}

.ar-marker-missing {
  margin-top: 10px;
  color: #ffcc66;
  font-size: 12px;
}`, "",{"version":3,"sources":["webpack://./src/app/ar/ar-view/ar-view.component.scss","webpack://./../../../../SCADIA-%E5%B7%A5%E4%BD%9C%E7%AB%99%E8%BF%81%E7%A7%BB/SCADIA-delivery/source/client/src/app/ar/ar-view/ar-view.component.scss"],"names":[],"mappings":"AAAA;EACI,cAAA;EACA,YAAA;EACA,WAAA;EACA,gBAAA;ACCJ;;ADEA;EACI,kBAAA;EACA,WAAA;EACA,YAAA;EACA,gBAAA;EACA,cAAA;EACA,8EAAA;ACCJ;;ADEA;EACI,kBAAA;EACA,QAAA;EACA,WAAA;EACA,YAAA;EACA,iBAAA;EACA,gBAAA;ACCJ;;ADEA;EACI,kBAAA;EACA,SAAA;EACA,UAAA;EACA,WAAA;EACA,UAAA;EACA,aAAA;EACA,uBAAA;EACA,8BAAA;EACA,SAAA;EACA,oBAAA;ACCJ;;ADEA;EACI,eAAA;EACA,gBAAA;EACA,iBAAA;EACA,0CAAA;ACCJ;;ADEA;EACI,eAAA;EACA,eAAA;EACA,gCAAA;EACA,0CAAA;ACCJ;;ADEA;EACI,oBAAA;ACCJ;;ADEA;EACI,gBAAA;EACA,YAAA;EACA,2CAAA;EACA,kBAAA;EACA,kCAAA;EACA,WAAA;EACA,cAAA;EACA,eAAA;ACCJ;;ADEA;;;EAGI,kBAAA;EACA,SAAA;EACA,QAAA;EACA,UAAA;EACA,kCAAA;EACA,gCAAA;EACA,kBAAA;EACA,2CAAA;EACA,kBAAA;EACA,kCAAA;EACA,WAAA;EACA,eAAA;EACA,kBAAA;ACCJ;;ADEA;EACI,uCAAA;ACCJ;;ADEA;EACI,uCAAA;ACCJ;;ADEA;EACI,kBAAA;EACA,UAAA;EACA,WAAA;EACA,YAAA;EACA,UAAA;EACA,gBAAA;EACA,gBAAA;EACA,kBAAA;EACA,+BAAA;EACA,cAAA;EACA,eAAA;EACA,iBAAA;ACCJ;;ADEA;EACI,gBAAA;EACA,uBAAA;EACA,mBAAA;ACCJ;;ADEA;EACI;IACI,oBAAA;IACA,sBAAA;ECCN;EDEE;IACI,WAAA;ECAN;EDGE;IACI,qBAAA;IACA,WAAA;IACA,WAAA;IACA,eAAA;ECDN;AACF;ADIA;EACI,kBAAA;EACA,SAAA;EACA,QAAA;EACA,gBAAA;EACA,mCAAA;EACA,oCAAA;EACA,cAAA;EAGA,gCAAA;EACA,+BAAA;EACA,UAAA;ACJJ;;ADOA;EACI,eAAA;EACA,aAAA;EACA,+BAAA;EACA,WAAA;ACJJ;;ADOA;EAEI,gBAAA;EACA,iBAAA;ACLJ;;ADQA;EACI,cAAA;EACA,gBAAA;EACA,iBAAA;ACLJ;;ADQA;EACI,gBAAA;EACA,cAAA;EACA,eAAA;ACLJ","sourcesContent":[":host {\r\n    display: block;\r\n    height: 100%;\r\n    width: 100%;\r\n    background: #111;\r\n}\r\n\r\n.ar-shell {\r\n    position: relative;\r\n    width: 100%;\r\n    height: 100%;\r\n    overflow: hidden;\r\n    color: #f7f9fb;\r\n    font-family: \"Segoe UI Symbol\", \"Roboto-Regular\", \"Helvetica Neue\", sans-serif;\r\n}\r\n\r\n.ar-video {\r\n    position: absolute;\r\n    inset: 0;\r\n   