import { Component, OnInit, AfterViewInit, OnDestroy, ViewChild, ChangeDetectorRef, Inject } from '@angular/core';
import { DOCUMENT, Location } from '@angular/common';
import { Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';
import { Observable, Subject, Subscription, combineLatest, fromEvent, map, merge, of, startWith, switchMap, takeUntil, timer } from 'rxjs';

import { environment } from '../environments/environment';

import { ProjectService } from './_services/project.service';
import { SettingsService } from './_services/settings.service';
import { UserGroups } from './_models/user';
import { AppService } from './_services/app.service';
import { HeartbeatService } from './_services/heartbeat.service';
import { AuthService } from './_services/auth.service';
import { HmiService } from './_services/hmi.service';
import { Utils } from './_helpers/utils';
import { EndPointApi } from './_helpers/endpointapi';

@Component({
	selector: 'app-root',
	templateUrl: './app.component.html',
	styleUrls: ['./app.component.scss']
})

export class AppComponent implements OnInit, AfterViewInit, OnDestroy {
	title = 'app';
	location: Location;
	showdev = false;
	isLoading = false;
	serverErrorBanner$: Observable<boolean>;

	@ViewChild('fabmenu', {static: false}) fabmenu: any;

	private subscriptionLoad: Subscription;
	private subscriptionShowLoading: Subscription;
	private destroy$ = new Subject<void>();
    private securityEnabled = false;

	constructor(@Inject(DOCUMENT) private document: Document,
		private router: Router,
		private appService: AppService,
		private projectService: ProjectService,
		private settingsService: SettingsService,
		private translateService: TranslateService,
		private heartbeatService: HeartbeatService,
		private cdr: ChangeDetectorRef,
		private hmiService: HmiService,
		private authService: AuthService,
		location: Location
	) {
		this.location = location;
	}

	ngOnInit() {
		// THE BUILD STAMP. Why: twice in a row a 'the menu does not work' report turned out to be a
		// browser still running an older bundle, and nothing on the page could tell them apart. The
		// stamp is in the console AND in the tab title, so 'which build is this' is answered by looking
		// at either, without DevTools.
		const BUILD = 'b-20261015-workspace';
		// eslint-disable-next-line no-console
		console.log(`SCADIA v${environment.version}  client build ${BUILD}`);
		this.document.title = this.document.title + '  [' + BUILD + ']';
		this.heartbeatService.startHeartbeatPolling();
		// Wall / kiosk presentation: no pointer, no scrollbars, no selection.
		if (Utils.isKioskMode()) {
			this.document.body.classList.add('scadia-kiosk');
		}
		// Publish the automatic chrome scale before the first paint; HomeComponent replaces it
		// with the configured value once the project is loaded.
		Utils.applyUiScale(Utils.computeUiScale());

		// capture events for the token refresh
		const activity$ = merge(
			fromEvent(document, 'click'),
			fromEvent(document, 'touchstart')
		);
		activity$.pipe(
			takeUntil(this.destroy$)
		).subscribe(() => this.heartbeatService.setActivity(true));

		// 账号活动审计：页面卸载时上报“退出”。浏览器关闭时服务端收不到任何请求，
		// sendBeacon 是唯一能尽力送达的方式——但它不保证送达，手册与合作说明都如实标注。
		window.addEventListener('pagehide', this.reportExit);


		this.serverErrorBanner$ = combineLatest([
			this.hmiService.onServerConnection$,
			this.authService.currentUser$
		]).pipe(
			switchMap(([connectionStatus, userProfile]) =>
				merge(
					of(false),
					timer(35000).pipe(map(() => (this.securityEnabled && !userProfile) ? false : true)),
				).pipe (
					startWith(false),
				)
			),
			takeUntil(this.destroy$)
		);
	}

	ngAfterViewInit() {
		try {
			this.settingsService.init();
			let hmi = this.projectService.getHmi();
			if (hmi) {
				this.checkSettings();
			}
			this.subscriptionLoad = this.projectService.onLoadHmi.subscribe(load => {
				this.checkSettings();
				this.applyCustomCss();
			}, error => {
				console.error('Error loadHMI');
			});
			// define user groups text
			this.translateService.get('general.usergroups').subscribe((txt: string) => {
				let grpLabels = txt.split(',');
				if (grpLabels && grpLabels.length > 0) {
					for (let i = 0; i < grpLabels.length && i < UserGroups.Groups.length; i++) {
						UserGroups.Groups[i].label = grpLabels[i];
					}
				}
			});
			// show loading manager
			this.subscriptionShowLoading = this.appService.onShowLoading.subscribe(show => {
				this.isLoading = show;
				this.cdr.detectChanges();
			}, error => {
				this.isLoading = false;
				console.error('Error to show loading');
			});
		}
		catch (err) {
			console.error(err);
		}
	}

	/** 每个浏览器标签页一个会话标识，仅用于去重与对账，不是安全凭据。 */
	private sessionId(): string {
		try {
			let id = sessionStorage.getItem('scadiaSessionId');
			if (!id) {
				id = (Date.now().toString(36) + Math.random().toString(36).slice(2, 10)).slice(0, 32);
				sessionStorage.setItem('scadiaSessionId', id);
			}
			return id;
		} catch (err) {
			return '';
		}
	}

	private reportExit = () => {
		try {
			const token = (window as any).scadiaAccessToken;
			if (!token) {
				return;
			}
			const url = EndPointApi.getURL() + '/api/session/exit';
			const body = new Blob([JSON.stringify({ token, reason: 'exit', sessionId: this.sessionId() })], { type: 'application/json' });
			if (navigator.sendBeacon && navigator.sendBeacon(url, body)) {
				return;
			}
			fetch(url, {
				method: 'POST',
				body,
				headers: { 'Content-Type': 'application/json' },
				credentials: 'same-origin',
				keepalive: true
			}).catch(() => { });
		} catch (err) {
			// 关闭页面时上报失败不应影响页面本身。
		}
	};

	ngOnDestroy() {
		try {
			window.removeEventListener('pagehide', this.reportExit);
			if (this.subscriptionLoad) {
				this.subscriptionLoad.unsubscribe();
			}
			if (this.subscriptionShowLoading) {
				this.subscriptionShowLoading.unsubscribe();
			}
		} catch (e) {
		}
		this.destroy$.next(null);
		this.destroy$.complete();
	}

	applyCustomCss() {
		let hmi = this.projectService.getHmi();
		if (hmi?.layout?.customStyles) {
			const style = this.document.createElement('style');
			style.textContent = hmi.layout.customStyles;
			this.document.head.appendChild(style);
		}
	}

	checkSettings() {
		let hmi = this.projectService.getHmi();
		if (hmi && hmi.layout && hmi.layout.showdev === false) {
			this.showdev = false;
		} else {
			this.showdev = true;
		}
		this.securityEnabled = this.projectService.isSecurityEnabled();
	}

    workspace(): boolean {
        const route = this.location.path().split('?')[0];
        if (!this.projectService.getViewFromId('v_zc_g1')) { return false; }
        if (Utils.isKioskMode() || route === '/view' || this.isArViewRoute(route) || route === '/editor' || route === '/lab') { return false; }
        if (!route || route === '/home') { return false; }
        if (route.startsWith('/home/')) { return /^\/home\/v_zc_(g[1-6]|home)$/.test(route); }
        return true;
    }

	isHidden() {
		const urlEnd = this.location.path();
		if (!urlEnd || urlEnd.startsWith('/home') || urlEnd === '/lab' || this.isArViewRoute(urlEnd)) {
			return true;
		}
		return false;
	}

	getClass() {
		const route = this.location.path();
		if (route.startsWith('/view')) {
            return 'work-void';
        }
		if (this.isArViewRoute(route)) {
            return 'work-void';
        }
		return (this.isHidden()) ? 'work-home' : 'work-editor';
	}

    showDevNavigation() {
        const route = this.location.path();
        if (route.startsWith('/view') || this.isArViewRoute(route) || Utils.isKioskMode()) {
            return false;
        }
        return this.showdev && !this.workspace();
    }

    private isArViewRoute(route: string): boolean {
        return route === '/ar' || route.startsWith('/ar?');
    }

	onGoTo(goto) {
		this.router.navigate([goto]);
		this.fabmenu.toggle();
		//TODO!
        if (!this.location.path().includes(goto) && ['home', 'lab'].indexOf(goto) !== -1) {
			if (goto === 'lab') {
				this.router.navigate(['']);
				setTimeout(() => {
					this.router.navigate([goto]);
				}, 0);
			}
		}
	}
}
