  flex: 1 1 140px;
}
:host .mat-column-created {
  flex: 1 1 100px;
}
:host .mat-column-expires {
  flex: 1 1 100px;
}
:host .mat-column-enabled {
  flex: 1 1 80px;
}
:host .mat-column-remove {
  flex: 0 0 60px;
}
