    display: block;
    height: 100%;
}

.header-panel {
    background-color: var(--headerBackground);
    color: var(--headerColor);
    position: absolute;
    top: 0px;
    left: 0px;
    height: 36px;
    width: 100%;
    text-align: center;
    line-height: 36px;
    border-bottom: 1px solid var(--headerBorder);
}

.header-panel mat-icon {
    display: inline-block;
    vertical-align: text-top;
}

.work-panel {
    position: absolute;
    top: 37px;
    left: 0px;
    right: 0px;
    bottom: 0px;
    background-color: var(--workPanelBackground);
    overflow: hidden;
}

.container {
    display: block;
    width: 100%;
    height: 100%;
    overflow-y: auto;
}

.mat-table {
    width: 100%;
}

.mat-row {
    min-height: 40px;
    height: 43px;
}

.mat-cell {
    font-size: 13px;
}

.mat-header-row {
    top: 0;
    position: sticky;
    z-index: 10;
    background-color: var(--workPanelBackground);
}

.mat-header-cell {
    font-size: 15px;
    position: sticky;
    top: 0;
    z-index: 11;
    background-color: var(--workPanelBackground);
}

.mat-column-select {
    overflow: visible;
    width: 50px;
}

.mat-column-name {
    flex: 1 1 120px;
}

.mat-column-type {
    flex: 0 0 100px;
}

.mat-column-receiver {
    flex: 3 1 180px;
}
.mat-column-scheduling {
    flex: 3 1 180px;
}
.mat-column-enabled {
    flex: 0 0 60px;
}

.mat-column-create {
    width: 50px;
}

.mat-column-remove {
    width: 50px;
}

.mat-column-expand {
    width: 50px;
}

tr.detail-row {
    height: 0;
}
  
  /* .example-element-row td {
    border-bottom-width: 0;
  } */
  
.report-details {
    overflow: hidden;
    display: flex;
}

.details-description {
    min-height: 100px;
    max-height: 360px;
    margin: 5px 10px;
    padding-left: 40px;
    width: 100%;
    overflow: auto;
}

.report-detail div {
    min-width: 600px;
    display: inline-block;
}

td.details-container {
    background-color: var(--workPanelExpandBackground);
}

/* 顶部两个视图：报表定义 / 账号活动 */
.header-views {
    position: absolute;
    right: 12px;
    top: 0;
    line-height: 36px;
    display: inline-flex;
    gap: 4px;
}

.header-views button {
    line-height: 30px;
    height: 30px;
    padding: 0 10px;
    min-width: 0;
    color: var(--headerColor);
    opacity: 0.75;
}

.header-views button.view-active {
    opacity: 1;
    font-weight: 600;
    border-bottom: 2px solid var(--headerColor);
}

.activity-work {
    overflow-y: auto;
}

.activity {
    padding: 14px 18px 28px;
}

.activity-filters {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-end;
    gap: 10px 16px;
    margin-bottom: 10px;
}

.activity-filters label {
    display: flex;
    flex-direction: column;
    font-size: 12px;
    line-height: 18px;
    color: var(--headerColor, #cfd8dc);
    gap: 2px;
}

.activity-filters input,
.activity-filters select {
    height: 30px;
    min-width: 180px;
    padding: 0 8px;
    font-size: 13px;
    color: #102d48;
    background: #ffffff;
    border: 1px solid #b0bec5;
    border-radius: 3px;
}

.activity-note {
    font-size: 12px;
    line-height: 18px;
    padding: 8px 10px;
    margin-bottom: 10px;
    color: #455a64;
    background: #eceff1;
    border-left: 3px solid #90a4ae;
    border-radius: 2px;
}

.activity-error {
    padding: 10px 12px;
    margin-bottom: 10px;
    color: #b71c1c;
    background: #ffebee;
    border-left: 3px solid #c62828;
}

.activity-loading,
.activity-empty {
    padding: 14px 2px;
    font-size: 13px;
    color: #546e7a;
}

.activity-table {
    width: 100%;
    background: transparent;
}

.activity-table th.mat-header-cell {
    font-size: 12px;
    font-weight: 600;
    color: #37474f;
    border-bottom: 1px solid #b0bec5;
}

.activity-table td.mat-cell {
    font-size: 13px;
    border-bottom: 1px solid #eceff1;
}

.activity-pager {
    display: flex;
    align-items: center;
    gap: 10px;
    padding-top: 10px;
    font-size: 12px;
    color: #546e7a;
}
