\n    }\r\n    &.drops-up-right {\r\n      transform-origin: 0 100%;\r\n    }\r\n    &.drops-down-left {\r\n      transform-origin: 100% 0;\r\n    }\r\n    &.drops-down-right {\r\n      transform-origin: 0 0;\r\n    }\r\n    &.drops-down-center {\r\n      transform-origin: 50%% 0;\r\n    }\r\n    &.drops-up-center {\r\n      transform-origin: 50%% 100%;\r\n    }\r\n    .calendar {\r\n      display: block;\r\n    }\r\n  }\r\n  &.hidden {\r\n    transition: all 0.1s ease;\r\n    transform: scale(0);\r\n    transform-origin: 0 0;\r\n    cursor: default;\r\n    -webkit-touch-callout: none;\r\n      -webkit-user-select: none;\r\n        -moz-user-select: none;\r\n          -ms-user-select: none;\r\n              user-select: none;\r\n    &.drops-up-left {\r\n      transform-origin: 100% 100%;\r\n    }\r\n    &.drops-up-right {\r\n      transform-origin: 0 100%;\r\n    }\r\n    &.drops-down-left {\r\n      transform-origin: 100% 0;\r\n    }\r\n    &.drops-down-right {\r\n      transform-origin: 0 0;\r\n    }\r\n    &.drops-down-center {\r\n      transform-origin: 50%% 0;\r\n    }\r\n    &.drops-up-center {\r\n      transform-origin: 50%% 100%;\r\n    }\r\n    \r\n    .calendar {\r\n      display: none;\r\n    }\r\n  }\r\n\r\n  .calendar {\r\n    /* display: none; */\r\n    max-width: $md-drppicker-width - ($md-drppicker-calendar-margin * 2);\r\n    margin: $md-drppicker-calendar-margin;\r\n\r\n    &.single {\r\n      .calendar-table {\r\n        border: none;\r\n      }\r\n    }\r\n\r\n    th, td {\r\n      padding: 0;\r\n      white-space: nowrap;\r\n      text-align: center;\r\n      min-width: 32px;\r\n      span {\r\n        pointer-events: none;\r\n      }\r\n    }\r\n  }\r\n\r\n  .calendar-table {\r\n    border: $md-drppicker-calendar-border-size solid $md-drppicker-calendar-border-color;\r\n    padding: $md-drppicker-calendar-margin;\r\n    border-radius: $md-drppicker-calendar-border-radius;\r\n    background-color: $md-drppicker-calendar-bg-color;\r\n  }\r\n\r\n 